package com.tripnest.controller; import com.tripnest.dto.ApiDtos.*; import com.tripnest.service.AuthService; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/auth") public class AuthController{final AuthService service; public AuthController(AuthService s){service=s;} @PostMapping("/register") public Auth register(@Valid @RequestBody Register x){return service.register(x);} @PostMapping("/login") public Auth login(@Valid @RequestBody Login x){return service.login(x);} }
